const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true, executablePath:'/usr/bin/chromium', args:['--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1280,height:900}}); const errors=[]; page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:3000');
 await page.locator('[data-map="lab"]').click();
 if(!(await page.locator('#previewTitle').innerText()).includes('NOVA-7')) throw new Error('map selection failed');
 await page.locator('#startBtn').click();
 if(!(await page.locator('.stage').evaluate(e=>e.classList.contains('playing')))) throw new Error('start failed');
 const canvas=page.locator('#gameCanvas'); const box=await canvas.boundingBox();
 for(const [x,y] of [[.32,.34],[.72,.32],[.54,.70]]) {
   await page.mouse.click(box.x+box.width*x,box.y+box.height*y); await page.waitForTimeout(100);
   await page.keyboard.press('e'); await page.waitForTimeout(120);
 }
 await page.waitForTimeout(1000);
 const progress=await page.locator('#hudProgress').innerText();
 const modal=await page.locator('#modal').evaluate(e=>e.classList.contains('show'));
 if(progress!=='3 / 3'||!modal) throw new Error(`task/win flow failed progress=${progress} modal=${modal}`);
 if(errors.length) throw new Error(errors.join('\n'));
 console.log('PASS: map selection, start, task interactions, win modal; no page errors');
 await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
