document.querySelectorAll('.mapselect button').forEach(b=>b.onclick=()=>{
  document.querySelectorAll('.mapselect button').forEach(x=>x.classList.remove('active'));
  b.classList.add('active');
  map=b.dataset.map;
  document.getElementById('mapName').textContent=mapData[map].name;
  scene.fog.density=map==='nova'?.048:.035;
  scene.fog.color.set(map==='nova'?0x100c0c:0x0a1014);
  red.intensity=map==='nova'?8:5;
  red.color.set(map==='nova'?0xff2d3f:0xb62037);
  const positions=map==='nova'?
    [new THREE.Vector3(-8,.1,-7),new THREE.Vector3(11,.1,2),new THREE.Vector3(-11,.1,9)]:
    [new THREE.Vector3(-8,.1,-7),new THREE.Vector3(8,.1,-7),new THREE.Vector3(8,.1,7)];
  tasks.forEach((task,i)=>{
    task.p.copy(positions[i]);
    task.ring.position.copy(task.p);
    task.ring.position.y=.32;
  });
  renderTasks();
});

